/// Kısa metin; {ad} yer tutucuları [p] ile dolar.
String bt(String lang, String key, [Map<String, Object> p = const {}]) {
  var s = Strings.pick(kBilgiTexts[key]!, lang);
  p.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}
